import json, random, importlib.util
spec = importlib.util.spec_from_file_location("m", "/app/submission/main.py")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

def true_depth(o, d=0):
    # root container has depth 1
    if isinstance(o, dict):
        d = d + 1
        return max([d] + [true_depth(v, d) for v in o.values()]) if o else d
    if isinstance(o, list):
        d = d + 1
        return max([d] + [true_depth(v, d) for v in o]) if o else d
    return d

rnd = random.Random(4)
bad = 0
for trial in range(4000):
    # build a random nested structure
    def gen(depth_budget):
        r = rnd.random()
        if depth_budget <= 0 or r < 0.35:
            return rnd.choice([1, 's', True, None, 2.5])
        if r < 0.7:
            return {('k%d' % rnd.randrange(3)): gen(depth_budget - 1)
                    for _ in range(rnd.randint(0, 3))}
        return [gen(depth_budget - 1) for _ in range(rnd.randint(0, 3))]
    obj = gen(8)
    txt = json.dumps(obj)
    td = true_depth(obj)
    try:
        m.check_depth(txt)
        raised = False
    except m.EJson:
        raised = True
    expect = td > 64
    if raised != expect:
        print('DEPTH MISMATCH', td, raised, txt[:120]); bad += 1
    # also confirm json.loads agrees it is valid
    try:
        json.loads(txt)
    except Exception as e:
        print('json.loads rejected our own doc?', e); bad += 1
    # check depth reported by our scan equals truth near the boundary
print('depth fuzz bad =', bad)

# boundary checks
for n in (63, 64, 65, 66):
    txt = '[' * n + ']' * n
    try:
        m.check_depth(txt); raised = False
    except m.EJson:
        raised = True
    print('depth', n, 'raised', raised)
